/**
 * M2 capture layer: observes Node-RED's send/complete/error events for a
 * single node invocation without letting the message actually route locally.
 *
 * No Temporal involved here. Pure @node-red/util `hooks` usage plus a
 * reversible prototype patch on Node.prototype.error (the only place a
 * synchronously-thrown node error surfaces, since it bypasses the
 * `onComplete` hook entirely - see Node.js `_emitInput`'s catch block).
 */

"use strict";

const DEFAULT_TIMEOUT_MS = 5000;

class Capture {
    constructor(opts) {
        opts = opts || {};
        this.timeoutMs = opts.timeoutMs || DEFAULT_TIMEOUT_MS;
        this._pending = new Map();
        this._installed = false;
        this._RED = null;
        this._NodeClass = null;
        this._origNodeError = null;

        this._onPreRoute = this._onPreRoute.bind(this);
        this._onComplete = this._onComplete.bind(this);
    }

    /** Register hooks + patch Node.prototype.error against a live RED runtime. */
    install(RED) {
        if (this._installed) {
            return;
        }
        this._RED = RED;
        RED.hooks.add("preRoute.temporal", this._onPreRoute);
        RED.hooks.add("onComplete.temporal", this._onComplete);

        // eslint-disable-next-line global-require
        const NodeClass = require("../../../@node-red/runtime/lib/nodes/Node.js");
        this._NodeClass = NodeClass;
        this._origNodeError = NodeClass.prototype.error;
        const self = this;
        NodeClass.prototype.error = function patchedError(logMessage, msg) {
            self._onNodeError(this, logMessage, msg);
            return self._origNodeError.apply(this, arguments);
        };
        this._installed = true;
    }

    /** Undo install(): remove hooks, restore Node.prototype.error, clear timers. */
    uninstall() {
        if (!this._installed) {
            return;
        }
        this._RED.hooks.remove("preRoute.temporal");
        this._RED.hooks.remove("onComplete.temporal");
        if (this._NodeClass && this._origNodeError) {
            this._NodeClass.prototype.error = this._origNodeError;
        }
        this._pending.forEach((entry) => clearTimeout(entry.timer));
        this._pending.clear();
        this._installed = false;
        this._RED = null;
        this._NodeClass = null;
        this._origNodeError = null;
    }

    /**
     * Run `fn` (which must trigger `nodeId` to receive `msg`) and resolve once
     * that invocation is done. Correlation key is `nodeId + msg._msgid`, not
     * `_msgid` alone, because `_msgid` is preserved across hops - keying on it
     * alone would collide the current invocation with the node's own outbound
     * sends of the same message.
     */
    around(nodeId, msg, fn) {
        if (!msg._msgid) {
            msg._msgid = `cap-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
        }
        const key = `${nodeId}::${msg._msgid}`;
        return new Promise((resolve, reject) => {
            const timer = setTimeout(() => {
                this._pending.delete(key);
                reject({ nodeId, error: new Error(`capture timed out after ${this.timeoutMs}ms`), timeout: true });
            }, this.timeoutMs);
            this._pending.set(key, { sends: [], resolve, reject, timer });
            try {
                fn();
            } catch (err) {
                this._settleError(key, nodeId, err);
            }
        });
    }

    _onPreRoute(sendEvent, done) {
        const msg = sendEvent.msg;
        const key = `${sendEvent.source.id}::${msg && msg._msgid}`;
        const pending = this._pending.get(key);
        if (pending) {
            pending.sends.push({ port: sendEvent.source.port, destinationId: sendEvent.destination.id, msg });
        }
        done(false);
    }

    _onComplete(completeEvent, done) {
        const nodeId = completeEvent.node.id;
        const msg = completeEvent.msg;
        const key = `${nodeId}::${msg && msg._msgid}`;
        if (this._pending.has(key)) {
            if (completeEvent.error) {
                this._settleError(key, nodeId, completeEvent.error);
            } else {
                this._settleResolve(key);
            }
        }
        done();
    }

    _onNodeError(node, logMessage, msg) {
        if (!msg || typeof msg !== "object") {
            return;
        }
        const key = `${node.id}::${msg._msgid}`;
        if (this._pending.has(key)) {
            const error = logMessage instanceof Error ? logMessage : new Error(String(logMessage));
            this._settleError(key, node.id, error);
        }
    }

    _settleResolve(key) {
        const pending = this._pending.get(key);
        if (!pending) {
            return;
        }
        clearTimeout(pending.timer);
        this._pending.delete(key);
        pending.resolve({ sends: pending.sends });
    }

    _settleError(key, nodeId, error) {
        const pending = this._pending.get(key);
        if (!pending) {
            return;
        }
        clearTimeout(pending.timer);
        this._pending.delete(key);
        pending.reject({ nodeId, error, sends: pending.sends });
    }
}

module.exports = { Capture, DEFAULT_TIMEOUT_MS };
